// TH18 v1.00a Extra, Boss1 nonspell (st07bs.ecl.txt:128-155).
// Source frame 0 is the first frame of the real boss task; the 120-frame opening
// buffer belongs to the training shell only (see report.md for the frame relation).
const TIME_LIMIT: int = 3780;      // 120 buffer + 3600 source timeout + tail
const OPENING_BUFFER: int = 120;

// st07bs.ecl.txt:2646 etSprite(A, 12, 14): TH18 type12 arrowhead, source color14.
const TH18_ARROWHEAD: int = 544;
const BULLET_COLOR: int = 14;

// st07bs.ecl.txt:2647 etCount(A, 3, 10): 3 lanes x 10 layers.
const RING_WAYS: int = 3;
const RING_LAYERS: int = 10;

// Boss_at1 EX chain (st07bs.ecl.txt:2650-2652):
//   0x2 ANIM            -> birth displacement position -= 4 * velocity (baked below)
//   0x200000 VELTIME    -> a=60, r=4.0, s=-9999994 (current bullet angle)
//   0x8 ANGLE_ACCEL     -> a=30, r=-0.1/frame, s=%E (+/-0.017453292 rad/frame, i.e. +/-1deg)
xformdef ARROW_EFFECT(start_speed: fx, e: angle) {
    set_accel((4fx - start_speed) / 60);
    wait(60);
    set_accel(-0.1fx);
    set_ang_vel(e);
    wait(30);
    set_accel(0fx);
    set_ang_vel(0deg);
}

// st07bs.ecl.txt:2641-2666 Boss_at1, one instance per source async task.
// step = %D (etAngle increment per volley), e = %E (ANGLE_ACCEL angle per frame).
async sub volley(step: angle, e: angle) {
    // st07bs.ecl.txt:2655 %F = %ANGLE_PLAYER, sampled once when the async first runs.
    var base: angle = aim_player();
    loop {
        // Source creation order is layer q outer, lane i inner (etOn reads etCount).
        for q in 0..RING_LAYERS {
            // st07bs.ecl.txt:2649 etSpeed(1.2f, 0.0f): v(q)=1.2+(0-1.2)*q/9.
            var speed: fx = 1.2fx * ((RING_LAYERS - 1 - q) as fx) / ((RING_LAYERS - 1) as fx);
            // etDist 32 minus the ANIM 4*velocity birth displacement.
            var d: fx = 32fx - 4fx * speed;
            for i in 0..RING_WAYS {
                // st07bs.ecl.txt:2648/2659 etAim(3) with alpha=%F, spread=0:
                // angle = F + 2*pi*i/3 (layer q adds q*0).
                var off: int = (i * 65536) / RING_WAYS;
                var a: angle = base + (off as angle);
                // st07bs.ecl.txt:2653-2654 offset (0,-24) then etDist along the
                // bullet angle. Source y is downward positive, as in the target.
                _ = fire(TH18_ARROWHEAD, BULLET_COLOR,
                         $self_x + d * cos(a),
                         $self_y - 24fx + d * sin(a),
                         speed, a, ARROW_EFFECT(speed, e), none);
            }
        }
        // st07bs.ecl.txt:2660-2661: %F += %D after the volley, then etOn.
        base = base + step;
        wait(10);   // st07bs.ecl.txt:2662 wait(10)
    }
}

// ---- moveRand(60, 4, 1.0) recipe, adapted to moveLimit(0,128,240,64) ----
// Source 0134 moveLimit center (0,128), full size 240x64:
// position box x in [-120,120], y in [96,160]; direction inner zone x +/-60,
// y 112..144 (movement.md "已复用: Stage01 BossCard2"). Shared state on the
// boss: int slot0 = next step index, fx slots0/1 = logical unit direction.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    // Target integrates phase 5 after ECL; arm the next source movement tick now.
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_move_rand() {
    // Source 412 direction: signed unit random * pi, kept as unwrapped BAM ints.
    var r: int = rand(65536) - 32768;
    var a: int = 0;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }   // source normalizes this branch only
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
        // Deliberately not normalized before the source fabs tests below.
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05 rad -> nearest BAM boundaries.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

// Every source wait inside the moving attack advances the moveRand state.
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

async sub boss_main() {
    // Training shell: real enemy invincible, source body/hurt frames kept.
    set_invuln(65535);      // source 0010/0011 prelude invuln; whole-card shell
    set_hitbox(24fx);       // source 0037 setHitbox(48,48) -> radius 24
    set_hurtbox(20fx);      // source 0036 setHurtbox(40,40) -> radius 20
    // 0130-0138 timerReset/setInterrupt/lifeMarker/stars/anm/sound: the phase
    // shell carries the 3600 timeout; the rest is presentation and omitted.
    wait(60);               // 0139
    spawn volley(8deg, 1deg);    // 0142 Boss_at1(0,3,10,0.13962634f,0.017453292f) async
    spawn volley(-8deg, -1deg);  // 0143 Boss_at1(1,3,10,-0.13962634f,-0.017453292f) async

    // 0144 goto Boss1_632 @0 then 0152-0153 -> Boss1_496; first moveRand at
    // source frame 160, then every 160 frames (0146-0151).
    wait(100);
    card_move_rand();
    card_wait(60);
    card_wait(100);
    card_move_rand();
    card_wait(60);
    for n in 0..10 {
        card_wait(100);
        card_move_rand();
        card_wait(60);
        card_wait(100);
        card_move_rand();
        card_wait(60);
    }
    // Source 3600 timeout hands this boss to BossCard1; next card is outside
    // this card. Keep the movement state until the source boundary, then leave.
    card_wait(20);
    return;
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // Source entry state: (0,128), static ABS, REL=0, source prelude life 18000.
    _ = spawn_enemy(0fx, 128fx, 18000, 0, 0, 0, boss_main);
    loop { wait(1); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
